### Fix #2 — Fix TCP_INFO Collection (Persistent Critical Blind Spot)

`tcp_info` has been all-zeros across every snapshot in this monitoring series. With the `obfs_write` max at 520ms, you need CWND and RTT data to distinguish congestion from buffer bloat. Replace `syscall` with `golang.org/x/sys/unix`:

```go
import (
    "golang.org/x/sys/unix"
    "net"
    "syscall"
)

type TCPDiagnostics struct {
    RTT_us         uint32 `json:"rtt_us"`
    RTTVar_us      uint32 `json:"rtt_var_us"`
    RetransmitSegs uint32 `json:"retransmit_segs"`
    LostSegs       uint32 `json:"lost_segs"`
    CwndSegs       uint32 `json:"cwnd_segs"`
    SndMSS         uint32 `json:"snd_mss"`
    Ssthresh       uint32 `json:"ssthresh"`
}

func collectTCPDiagnostics(conn net.Conn) (TCPDiagnostics, error) {
    // Unwrap to raw TCP connection — adjust for your wrapper chain
    // e.g., TLSConn → ObfsConn → *net.TCPConn
    type rawConner interface {
        SyscallConn() (syscall.RawConn, error)
    }

    rc, ok := conn.(rawConner)
    if !ok {
        return TCPDiagnostics{}, fmt.Errorf("conn does not expose SyscallConn")
    }

    raw, err := rc.SyscallConn()
    if err != nil {
        return TCPDiagnostics{}, err
    }

    var info *unix.TCPInfo
    var infoErr error

    raw.Control(func(fd uintptr) {
        info, infoErr = unix.GetsockoptTCPInfo(
            int(fd), unix.IPPROTO_TCP, unix.TCP_INFO,
        )
    })

    if infoErr != nil {
        return TCPDiagnostics{}, infoErr
    }

    return TCPDiagnostics{
        RTT_us:         info.Rtt,
        RTTVar_us:      info.Rttvar,
        RetransmitSegs: info.Retrans,      // current unACKed retransmits
        LostSegs:       info.Lost,
        CwndSegs:       info.Snd_cwnd,
        SndMSS:         info.Snd_mss,
        Ssthresh:       info.Snd_ssthresh,
    }, nil
}

// Emit a structured warning when diagnostics indicate congestion:
func checkCongestionAlerts(d TCPDiagnostics) {
    if d.CwndSegs > 0 && d.Ssthresh > 0 && d.CwndSegs < d.Ssthresh/2 {
        log.Printf("ALERT: CWND collapse detected: cwnd=%d ssthresh=%d — "+
            "severe congestion, throughput likely <25%% of baseline",
            d.CwndSegs, d.Ssthresh)
    }
    if d.RTT_us > 200_000 {
        log.Printf("WARN: High RTT: %.1fms — possible bufferbloat or "+
            "routing issue", float64(d.RTT_us)/1000)
    }
    if d.RetransmitSegs > 50 {
        log.Printf("WARN: Elevated retransmits: %d — packet loss on path",
            d.RetransmitSegs)
    }
}
```

**Expected impact:** Enables detection of the congestion events causing `obfs_write` max=520ms. Without this, you cannot distinguish a congested path from a stalled application.

