// CORRECT PATTERN — snapshot on every request with timeout:

func (s *Server) handleMetrics(w http.ResponseWriter, r *http.Request) {
    // Use a tight deadline so a blocked metrics collection
    // doesn't hold up the HTTP response indefinitely.
    ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
    defer cancel()

    snapshot, err := s.collectMetricsSnapshot(ctx)
    if err != nil {
        // Return last known good + staleness flag rather than
        // silently serving stale data as if it were fresh.
        w.Header().Set("X-Metrics-Stale", "true")
        w.Header().Set("X-Metrics-Error", err.Error())
        w.WriteHeader(http.StatusPartialContent)
        // Still encode whatever we have — stale data with a flag
        // is better than no data.
        if s.lastGoodSnapshot != nil {
            json.NewEncoder(w).Encode(s.lastGoodSnapshot)
        }
        return
    }

    s.lastGoodSnapshot = snapshot
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(snapshot)
}

// collectMetricsSnapshot builds a fresh snapshot under timeout.
// Each histogram read must be non-blocking or use select with ctx.Done().
func (s *Server) collectMetricsSnapshot(ctx context.Context) (*MetricsSnapshot, error) {
    type result struct {
        snap *MetricsSnapshot
        err  error
    }
    ch := make(chan result, 1)

    go func() {
        snap := &MetricsSnapshot{
            Timestamp: time.Now(),
            // Read each histogram atomically. If your histogram
            // implementation holds a mutex, this will unblock
            // a deadlock diagnosis — the goroutine will not return
            // within the 2s timeout, triggering the stale path above.
            Stages:   s.perf.Snapshot(), // must be implemented as below
        }
        ch <- result{snap, nil}
    }()

    select {
    case r := <-ch:
        return r.snap, r.err
    case <-ctx.Done():
        return nil, fmt.Errorf("metrics snapshot timed out: %w", ctx.Err())
    }
}
