// health.go

type MetricsHealthChecker struct {
    lastCount    int64
    lastChecked  time.Time
    frozenSince  *time.Time
    mu           sync.Mutex
}

func (c *MetricsHealthChecker) Check(currentCount int64) HealthStatus {
    c.mu.Lock()
    defer c.mu.Unlock()

    now := time.Now()

    // On first call or after activity, reset frozen timer.
    if currentCount != c.lastCount {
        c.lastCount = currentCount
        c.lastChecked = now
        c.frozenSince = nil
        return HealthStatusOK
    }

    // Count unchanged. Start or extend frozen window.
    if c.frozenSince == nil {
        c.frozenSince = &now
    }

    frozenDuration := now.Sub(*c.frozenSince)

    switch {
    case frozenDuration > 10*time.Minute:
        return HealthStatusCritical // "metrics_frozen_critical"
    case frozenDuration > 2*time.Minute:
        return HealthStatusDegraded // "metrics_frozen"
    default:
        return HealthStatusOK
    }
}
