The blocked goroutine is holding a `tun.Read()` call with no deadline. On idle TUN devices, this call never returns. When the session that owns the goroutine is torn down, the goroutine cannot exit because it is permanently blocked in a syscall. The fix requires a poll loop with `SetReadDeadline`.

```go
// tun_reader.go — complete, copy-paste ready implementation

package vpn

import (
    "context"
    "errors"
    "io"
    "net"
    "sync"
    "time"

    "go.uber.org/zap"
)

const (
    tunPollInterval = 200 * time.Millisecond
    tunReadBufSize  = 1<<16 + 4 // 65540: full IPv6 MTU + TUN header
    tunChanBuffer   = 64
)

// TUNReader wraps a TUN device and provides a channel-based read API
// that respects context cancellation. The underlying Read call is
// given a rolling deadline so blocked goroutines can exit promptly.
type TUNReader struct {
    dev    TUNDevice // must implement SetReadDeadline(time.Time) error
    ch     chan tunPacket
    cancel context.CancelFunc
    wg     sync.WaitGroup
    log    *zap.Logger
}

type tunPacket struct {
    data []byte
    err  error
}

// TUNDevice is the minimal interface required. Your implementation
// must support SetReadDeadline — without it, the poll loop cannot work.
type TUNDevice interface {
    Read(buf []byte) (int, error)
    Write(buf []byte) (int, error)
    SetReadDeadline(t time.Time) error
}

// NewTUNReader starts the background poll goroutine. Call Stop() to
// cleanly shut it down before the owning session is torn down.
func NewTUNReader(ctx context.Context, dev TUNDevice, log *zap.Logger) *TUNReader {
    ctx, cancel := context.WithCancel(ctx)
    r := &TUNReader{
        dev:    dev,
        ch:     make(chan tunPacket, tunChanBuffer),
        cancel: cancel,
        log:    log,
    }
    r.wg.Add(1)
    go r.loop(ctx)
    return r
}

func (r *TUNReader) loop(ctx context.Context) {
    defer r.wg.Done()
    defer close(r.ch)

    buf := make([]byte, tunReadBufSize)

    for {
        // Check for cancellation before each read attempt.
        // This handles the case where the context was cancelled
        // while we were processing the previous packet.
        select {
        case <-ctx.Done():
            return
        default:
        }

        // Set a rolling deadline. If no packet arrives within
        // tunPollInterval, Read returns a timeout error and we
        // loop back to check ctx.Done(). This is the critical
        // difference from a bare tun.Read() with no deadline.
        if err := r.dev.SetReadDeadline(time.Now().Add(tunPollInterval)); err != nil {
            // SetReadDeadline failure is fatal — we cannot guarantee
            // the goroutine will ever exit without it.
            r.log.Error("tun: SetReadDeadline failed, exiting reader",
                zap.Error(err))
            select {
            case r.ch <- tunPacket{err: err}:
            case <-ctx.Done():
            }
            return
        }

        n, err := r.dev.Read(buf)

        if err != nil {
            // Distinguish timeout (expected) from real errors.
            var netErr net.Error
            if errors.As(err, &netErr) && netErr.Timeout() {
                // Poll interval expired with no data. Check ctx and retry.
                continue
            }
            // io.EOF or device closed — propagate and exit.
            if errors.Is(err, io.EOF) {
                return
            }
            // Real error — send upstream and exit.
            select {
            case r.ch <- tunPacket{err: err}:
            case <-ctx.Done():
            }
            return
        }

        if n == 0 {
            continue
        }

        // Copy the slice — buf will be reused on next iteration.
        pkt := make([]byte, n)
        copy(pkt, buf[:n])

        select {
        case r.ch <- tunPacket{data: pkt}:
        case <-ctx.Done():
            return
        }
    }
}

// Packets returns the read channel. Callers must also select on their
// context to avoid blocking if the TUNReader is stopped.
func (r *TUNReader) Packets() <-chan tunPacket {
    return r.ch
}

// Stop cancels the poll loop and waits for the goroutine to exit.
// Maximum wait is approximately tunPollInterval (200ms).
// Call this in your session teardown path BEFORE closing the TUN device.
func (r *TUNReader) Stop() {
    r.cancel()
    r.wg.Wait()
}

// --- Integration in your session egress loop ---

func (s *Session) runEgress(ctx context.Context) error {
    reader := NewTUNReader(ctx, s.tun, s.log)
    defer reader.Stop() // guaranteed cleanup, max 200ms

    for {
        select {
        case pkt, ok := <-reader.Packets():
            if !ok {
                return nil // reader stopped cleanly
            }
            if pkt.err != nil {
                return fmt.Errorf("tun read: %w", pkt.err)
            }
            if err := s.processEgressPacket(pkt.data); err != nil {
                return err
            }

        case <-ctx.Done():
            return ctx.Err()
        }
    }
}
```

**Expected impact:** Eliminates goroutine leak entirely. `tun_read` max will reset on next restart. Mean will drop from 131ms toward the true p50 of ~1µs.

