// obfsconn.go — TCP keepalive + application-level heartbeat

// Step 1: Set TCP keepalive on the underlying connection.
// This detects dead peers at the OS level without waiting
// for a read timeout.
func configureServerConn(conn net.Conn) error {
    tc, ok := conn.(*net.TCPConn)
    if !ok {
        return nil // not TCP, skip
    }
    if err := tc.SetKeepAlive(true); err != nil {
        return err
    }
    // Send keepalive probe after 15s idle (default is 2h — far too long).
    if err := tc.SetKeepAlivePeriod(15 * time.Second); err != nil {
        return err
    }
    return nil
}

// Step 2: In ObfsConn.Read, distinguish timeout from dead peer.
// Your current code appears to use a 30s read deadline globally.
// Replace with a rolling deadline that resets on each successful read.

type ObfsConn struct {
    conn        net.Conn
    readTimeout time.Duration // e.g., 30s
    // ... other fields
}

func (c *ObfsConn) Read(b []byte) (int, error) {
    // Rolling deadline: reset before every read, not once at open.
    if err := c.conn.SetReadDeadline(time.Now().Add(c.readTimeout)); err != nil {
        return 0, err
    }
    n, err := c.conn.Read(b)
    if err != nil {
        var netErr net.Error
        // On timeout: connection may still be alive (just idle).
        // Let the caller decide whether to retry or close.
        if errors.As(err, &netErr) && netErr.Timeout() {
            return 0, ErrReadTimeout // sentinel your own type
        }
        return 0, err
    }
    return n, nil
}

// Step 3: Application-level PING/PONG on the mux layer.
// If the mux protocol supports it (smux does), enable keepalive:

import "github.com/xtaci/smux"

func newMuxSession(conn net.Conn, isServer bool) (*smux.Session, error) {
    cfg := smux.DefaultConfig()
    cfg.KeepAliveInterval = 10 * time.Second  // send PING every 10s
    cfg.KeepAliveTimeout  = 30 * time.Second  // close if no PONG in 30s
    cfg.MaxFrameSize      = 32 * 1024         // tune for your MTU
    if err := smux.VerifyConfig(cfg); err != nil {
        return nil, err
    }
    if isServer {
        return smux.Server(conn, cfg)
    }
    return smux.Client(conn, cfg)
}
